#!/usr/bin/env python3
"""
citation-guard.py

Deterministic differential citation-integrity guard for the proofread pipeline
(src/skills/proofread/SKILL.md Step 4). Reads a changes-schema.json payload
(src/skills/proofread/references/changes-schema.json) plus the PROOF_BASE text
file the changes were found against, and for every change whose `before` or
`after` span overlaps a citation, quotation, page-reference, or footnote
token, downgrades that change to `applied: false` with
`skipReason: "citation-guard"` -- it is never dropped from the output.

Token categories are the ones described in prose in
src/skills/proofread/SKILL.md:73-78 (footnote markers, parenthetical
citations incl. Hebrew forms and traditional source refs, quotations,
page numbers / locators); that section states the categories but does not
ship literal regexes, so the patterns below are this script's own
implementation of that prose contract.

Matching rules (recorded gotchas from the plan of record):
  - Both sides of every comparison are NFC-normalized before matching --
    substring/regex matching on raw Hebrew text is fragile under NFC/NFD
    normalization drift (composed niqqud, geresh/gershayim precomposed vs.
    combining forms).
  - There is NEVER a whole-file substring replacement/fallback. A change's
    `before`/`after` strings are checked directly against the token
    patterns, and -- when the change's `line` resolves inside PROOF_BASE --
    against the token spans found on that single line, by locating the
    `before`/`after` substring's offset within the line. Nothing wider than
    one line is ever scanned for a single change.
  - A change with no overlap anywhere is emitted completely unchanged
    (it is not "no-matched" or annotated -- silence here means "this guard
    had nothing to say about it", matching the schema's optional `applied`/
    `skipReason` fields). A change that cannot be located on its line at all
    is likewise passed through untouched rather than dropped -- this guard
    never removes an item from the list, whatever happens during matching.

Usage:
    python3 citation-guard.py --changes changes.json --proof-base article.md [--json]

--changes     Path to a JSON file matching changes-schema.json: either the
              full object ({"stage": ..., "changes": [...]}) or a bare JSON
              array of change objects.
--proof-base  Path to the PROOF_BASE text file the changes reference (read
              for line-level context only).
--json        Emit JSON (currently the only supported output format; kept
              explicit like sibling scripts in this directory).

Always prints the full annotated changes payload (same shape as the input)
to stdout as JSON and exits 0, unless the input files cannot be read/parsed
(exit 2, usage/IO error).

No third-party dependencies -- Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
import unicodedata
from pathlib import Path
from typing import Optional

# --- Citation / quotation / footnote token patterns -------------------------
# Derived from the prose categories in proofread/SKILL.md:73-78. Compiled once.

FOOTNOTE_RE = re.compile(r"\[\^[^\]\n]+\]:?")

# Parenthetical citations: "(Author, 2019, p. 45)" and Hebrew forms
# "(כהן, 2019, עמ׳ 45)" -- any parenthetical containing a 4-digit year or the
# Hebrew page-locator abbreviation עמ׳.
PAREN_CITATION_RE = re.compile(r"\([^()\n]*(?:\d{4}|עמ׳)[^()\n]*\)")

# Traditional source refs, e.g. "בבלי ברכות י, ע״ב" / "בראשית א, א" --
# Hebrew tractate/book-chapter-verse style refs using a Talmud folio-side
# marker or a short comma-separated Hebrew reference.
TALMUD_FOLIO_RE = re.compile(r'ע["״][אב]')
# Hebrew Bible book names, supplied by the deterministic Tanakh book list.
_TANAKH_BOOKS = ("בראשית|שמות|ויקרא|במדבר|דברים|יהושע|שופטים|שמואל|מלכים|ישעיהו|ירמיהו|יחזקאל|הושע|יואל|עמוס|עובדיה|יונה|מיכה|נחום|חבקוק|צפניה|חגי|זכריה|מלאכי|תהלים|משלי|איוב|שיר השירים|רות|איכה|קהלת|אסתר|דניאל|עזרא|נחמיה|דברי הימים")
BOOK_CHAPTER_VERSE_RE = re.compile(rf"(?<![א-ת])(?:{_TANAKH_BOOKS})\s+[א-ת]{1,3},\s+[א-ת]{1,3}(?![א-ת])")

# Quotations (straight and Hebrew geresh/gershayim pairs), non-greedy within
# one line so an unrelated later quote on the same line isn't swallowed.
QUOTE_PATTERNS = [
    re.compile(r'"[^"\n]*"'),
    re.compile(r"״(?=[^״\n]{4,}״)[^״\n]{4,}״"),
    re.compile(r"'[^'\n]*'"),
]

# Page numbers / locators: "p. 45", "pp. 45-47", "עמ׳ 45" (already covered by
# PAREN_CITATION_RE when inside parens, kept here for bare, non-parenthetical
# occurrences too).
LOCATOR_RE = re.compile(r"\bpp?\.\s*\d+(?:[-–]\d+)?\b")

TOKEN_PATTERNS = [
    FOOTNOTE_RE,
    PAREN_CITATION_RE,
    TALMUD_FOLIO_RE,
    BOOK_CHAPTER_VERSE_RE,
    LOCATOR_RE,
    *QUOTE_PATTERNS,
]


def _nfc(text: Optional[str]) -> Optional[str]:
    """NFC-normalize, tolerating None (the schema allows `after: null`)."""
    if text is None:
        return None
    return unicodedata.normalize("NFC", text)


def _token_spans(line_text: str) -> list[tuple[int, int]]:
    spans: list[tuple[int, int]] = []
    for pattern in TOKEN_PATTERNS:
        for match in pattern.finditer(line_text):
            spans.append((match.start(), match.end()))
    return spans


def _spans_overlap(a_start: int, a_end: int, b_start: int, b_end: int) -> bool:
    return a_start < b_end and b_start < a_end


def _snippet_matches_token(snippet: str) -> bool:
    return any(pattern.search(snippet) for pattern in TOKEN_PATTERNS)


def _snippet_overlaps_line_token(snippet: str, line_text_norm: str) -> bool:
    """Locate `snippet` inside the (already NFC-normalized) line and check
    whether its span overlaps any citation/quotation token span on that line.
    Never falls back to a whole-file/whole-text scan -- only this one line.
    """
    idx = line_text_norm.find(snippet)
    if idx == -1:
        return False
    span_start, span_end = idx, idx + len(snippet)
    for token_start, token_end in _token_spans(line_text_norm):
        if _spans_overlap(span_start, span_end, token_start, token_end):
            return True
    return False


def change_overlaps_guard_token(change: dict, proof_base_lines: list[str]) -> bool:
    """True if `change`'s `before` or `after` overlaps a citation/quotation/
    footnote/page-locator token, per the rules documented in the module
    docstring.
    """
    before_norm = _nfc(change.get("before"))
    after_norm = _nfc(change.get("after"))

    for snippet in (before_norm, after_norm):
        if snippet and _snippet_matches_token(snippet):
            return True

    line_no = change.get("line")
    if isinstance(line_no, int) and 1 <= line_no <= len(proof_base_lines):
        line_norm = _nfc(proof_base_lines[line_no - 1])
        for snippet in (before_norm, after_norm):
            if snippet and _snippet_overlaps_line_token(snippet, line_norm):
                return True

    return False


def guard_changes(payload, proof_base_text: str):
    """Apply the citation-integrity guard to `payload` (either the full
    changes-schema object or a bare list of change objects) and return the
    same shape with overlapping changes downgraded in place. Nothing is ever
    removed from the list.
    """
    proof_base_lines = proof_base_text.splitlines()

    if isinstance(payload, dict):
        changes = payload.get("changes", [])
    elif isinstance(payload, list):
        changes = payload
    else:
        raise ValueError("changes payload must be a JSON object or array")

    annotated = []
    for change in changes:
        if change_overlaps_guard_token(change, proof_base_lines):
            downgraded = dict(change)
            downgraded["applied"] = False
            downgraded["skipReason"] = "citation-guard"
            annotated.append(downgraded)
        else:
            annotated.append(change)

    if isinstance(payload, dict):
        result = dict(payload)
        result["changes"] = annotated
        return result
    return annotated


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Deterministic differential citation-integrity guard for proofread changes."
    )
    parser.add_argument(
        "--changes",
        required=True,
        help="Path to a JSON file matching changes-schema.json (object or bare array).",
    )
    parser.add_argument(
        "--proof-base",
        required=True,
        help="Path to the PROOF_BASE text file the changes reference.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Emit JSON output (currently the only supported format).",
    )
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        payload = json.loads(Path(args.changes).read_text(encoding="utf-8"))
        proof_base_text = Path(args.proof_base).read_text(encoding="utf-8")
    except OSError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2
    except json.JSONDecodeError as exc:
        print(json.dumps({"error": f"invalid JSON in --changes: {exc}"}), file=sys.stderr)
        return 2

    try:
        result = guard_changes(payload, proof_base_text)
    except ValueError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2

    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
